begin;
-- Existing membership JSON is preserved: no automatic permission grants.
create or replace function jioflow_private.has_permission(sid uuid,permission_name text) returns boolean language sql stable security definer set search_path='' as $$
 select jioflow_private.staff_has_permission(sid,permission_name) or (permission_name in('users','assign','booking','products','import','export','profit','settings','approval','logout','integration','pull','price','discount','advance') and exists(select 1 from public.jf_memberships where id=jioflow_private.agent_member(sid) and permissions->permission_name='true'::jsonb));
$$;
create or replace function jioflow_private.reads_finance(target_shop uuid) returns boolean language sql stable security definer set search_path='' as $$select jioflow_private.has_permission(target_shop,'profit')$$;
do $patch$declare body text;begin body:=pg_get_functiondef('public.jf_save_profile_before_agent_sessions(uuid,jsonb)'::regprocedure);if position($old$if desired_role='agent' and k in ('users','products','export','profit','settings','approval','logout','integration') and v='true'::jsonb then raise exception 'Agents cannot receive administrative or profit access.';end if;$old$ in body)=0 then raise exception 'Unexpected installed definition: public.jf_save_profile_before_agent_sessions(uuid,jsonb)';end if;body:=replace(body,$old$if desired_role='agent' and k in ('users','products','export','profit','settings','approval','logout','integration') and v='true'::jsonb then raise exception 'Agents cannot receive administrative or profit access.';end if;$old$,$new$$new$);execute body;end$patch$;
do $patch$declare body text;begin body:=pg_get_functiondef('public.jf_save_profile(uuid,jsonb)'::regprocedure);if position($old$ or (m.role='agent' and k in ('users','products','export','profit','settings','approval','logout','integration') and v='true'::jsonb)$old$ in body)=0 then raise exception 'Unexpected installed definition: public.jf_save_profile(uuid,jsonb)';end if;body:=replace(body,$old$ or (m.role='agent' and k in ('users','products','export','profit','settings','approval','logout','integration') and v='true'::jsonb)$old$,$new$$new$);execute body;end$patch$;
do $patch$declare body text;begin body:=pg_get_functiondef('public.jf_workspace_tools(uuid,text,jsonb)'::regprocedure);if position($old$ or jioflow_private.agent_member(target_shop) is not null then raise exception 'Layout editing$old$ in body)=0 then raise exception 'Unexpected installed definition: public.jf_workspace_tools(uuid,text,jsonb)';end if;body:=replace(body,$old$ or jioflow_private.agent_member(target_shop) is not null then raise exception 'Layout editing$old$,$new$ then raise exception 'Layout editing$new$);execute body;end$patch$;
do $patch$declare body text;begin body:=pg_get_functiondef('public.jf_workspace_tools(uuid,text,jsonb)'::regprocedure);if position($old$ or jioflow_private.agent_member(target_shop) is not null then raise exception 'Settings editing$old$ in body)=0 then raise exception 'Unexpected installed definition: public.jf_workspace_tools(uuid,text,jsonb)';end if;body:=replace(body,$old$ or jioflow_private.agent_member(target_shop) is not null then raise exception 'Settings editing$old$,$new$ then raise exception 'Settings editing$new$);execute body;end$patch$;
do $patch$declare body text;begin body:=pg_get_functiondef('public.jf_status_settings(uuid,jsonb,jsonb,jsonb)'::regprocedure);if position($old$ and jioflow_private.agent_member(target_shop) is null;$old$ in body)=0 then raise exception 'Unexpected installed definition: public.jf_status_settings(uuid,jsonb,jsonb,jsonb)';end if;body:=replace(body,$old$ and jioflow_private.agent_member(target_shop) is null;$old$,$new$;$new$);execute body;end$patch$;
do $patch$declare body text;begin body:=pg_get_functiondef('public.jf_workspace_page(uuid,text,jsonb,integer)'::regprocedure);if position($old$ or jioflow_private.agent_member(target_shop) is not null then raise exception 'Advanced follow-up filters require Creator, Owner or Admin access.'$old$ in body)=0 then raise exception 'Unexpected installed definition: public.jf_workspace_page(uuid,text,jsonb,integer)';end if;body:=replace(body,$old$ or jioflow_private.agent_member(target_shop) is not null then raise exception 'Advanced follow-up filters require Creator, Owner or Admin access.'$old$,$new$ then raise exception 'Follow-up access required.'$new$);execute body;end$patch$;
do $patch$declare body text;begin body:=pg_get_functiondef('public.jf_followup_filter_options(uuid)'::regprocedure);if position($old$ or jioflow_private.agent_member(target_shop) is not null then raise exception 'Advanced follow-up filters require Creator, Owner or Admin access.'$old$ in body)=0 then raise exception 'Unexpected installed definition: public.jf_followup_filter_options(uuid)';end if;body:=replace(body,$old$ or jioflow_private.agent_member(target_shop) is not null then raise exception 'Advanced follow-up filters require Creator, Owner or Admin access.'$old$,$new$ then raise exception 'Follow-up access required.'$new$);execute body;end$patch$;
-- Delegated Agent tools stay inside the same active business and approved session.
create or replace function jioflow_private.manages_shop(target_shop uuid) returns boolean language sql stable security definer set search_path='' as $$
 select jioflow_private.is_creator() or jioflow_private.owns_shop(target_shop) or exists(select 1 from public.jf_memberships m join public.jf_profiles p on p.id=m.user_id join public.jf_shops s on s.id=m.shop_id where m.shop_id=target_shop and m.user_id=auth.uid() and m.status='active' and m.role in('admin','agent') and m.permissions->'users'='true'::jsonb and s.active and p.active and p.deleted_at is null and (m.role='admin' or m.id=jioflow_private.agent_member(target_shop)));
$$;
create or replace function jioflow_private.can_manage_lower(target_user uuid,permission_name text default 'users') returns boolean language sql stable security definer set search_path='' as $$
 select target_user<>auth.uid() and exists(select 1 from public.jf_profiles p join public.jf_memberships m on m.user_id=p.id where p.id=target_user and p.platform_role is distinct from 'creator' and p.deleted_at is null and m.status<>'removed' and not exists(select 1 from public.jf_shops s where s.owner_id=p.id) and jioflow_private.has_permission(m.shop_id,permission_name) and (jioflow_private.owns_shop(m.shop_id) and m.role in('admin','agent') or m.role='agent' and exists(select 1 from public.jf_memberships a where a.shop_id=m.shop_id and a.user_id=auth.uid() and a.role in('admin','agent') and a.status='active' and (a.role='admin' or a.id=jioflow_private.agent_member(m.shop_id)))));
$$;
-- Only Creator/Owner/Admin may delegate permissions, including when an Agent has user-management tools.
do $patch$declare body text;begin body:=pg_get_functiondef('public.jf_save_profile(uuid,jsonb)'::regprocedure);body:=replace(body,'begin','begin
 if details?''permissions'' and exists(select 1 from public.jf_memberships where user_id=auth.uid() and role=''agent'' and status<>''removed'') then raise exception ''Only Creator, Owner or Admin can change permissions.'' using errcode=''42501'';end if;');execute body;end$patch$;
-- Approval is a separate permission, and no Agent can approve their own login.
do $patch$declare body text;begin body:=pg_get_functiondef('public.jf_approve_agent(uuid,boolean)'::regprocedure);body:=replace(body,'not jioflow_private.manages_shop(a.shop_id)','(a.user_id=auth.uid() or not (jioflow_private.is_creator() or jioflow_private.owns_shop(a.shop_id) or jioflow_private.has_permission(a.shop_id,''approval'')))');execute body;end$patch$;
create policy jf_delegated_agent_approval_read on public.jf_agent_sessions for select to authenticated using(jioflow_private.has_permission(shop_id,'approval'));
do $patch$declare body text;begin body:=pg_get_functiondef('public.jf_performer_periods(uuid)'::regprocedure);body:=replace(body,' and jioflow_private.agent_member(target_shop) is null;',';');execute body;end$patch$;
-- Peer-directory reads for a delegated Agent action never expose Owner/Admin accounts.
create or replace function jioflow_private.reads_agent_peer(target_user uuid) returns boolean language sql stable security definer set search_path='' as $$
 select target_user<>auth.uid() and exists(select 1 from public.jf_memberships m join public.jf_profiles p on p.id=m.user_id where m.user_id=target_user and m.role='agent' and m.status<>'removed' and p.deleted_at is null and p.platform_role is distinct from 'creator' and not exists(select 1 from public.jf_shops s where s.owner_id=target_user) and jioflow_private.agent_member(m.shop_id) is not null and (jioflow_private.has_permission(m.shop_id,'logout') or jioflow_private.has_permission(m.shop_id,'approval')));
$$;
revoke all on function jioflow_private.reads_agent_peer(uuid) from public,anon;
grant execute on function jioflow_private.reads_agent_peer(uuid) to authenticated;
create policy jf_delegated_agent_profile_read on public.jf_profiles for select to authenticated using(jioflow_private.reads_agent_peer(id));
create policy jf_delegated_agent_member_read on public.jf_memberships for select to authenticated using(role='agent' and jioflow_private.reads_agent_peer(user_id));
insert into public.jf_schema_versions(version) values('047_agent_permissions_filters') on conflict do nothing;
commit;
